// 1. Проверяем наличие бинарных данных
const binaryData = $input.item.binary;
if (!binaryData || !binaryData.file || !binaryData.rules) {
  throw new Error("Missing 'file' or 'rules' parameter in request.");
}

// 2. Читаем файл логов
const logBuffer = await this.helpers.getBinaryDataBuffer(0, 'file');
const logText = logBuffer.toString('utf-8');

// 3. Читаем файл правил (rules.json)
const rulesBuffer = await this.helpers.getBinaryDataBuffer(0, 'rules');
const rulesJson = JSON.parse(rulesBuffer.toString('utf-8'));

// 4. Получаем тип лога
const body = $('Webhook').item.json.body || {};
const logType = body.type || 'ssh';

// 5. Разбиваем лог на строки
const lines = logText.split(/\r?\n/).filter(line => line.trim() !== '');

if (lines.length === 0) {
  return [{ json: { log_line: '', type: logType, rules: rulesJson, is_empty: true } }];
}

// 6. Передаем в следующий узел строку лога, тип и САМИ ПРАВИЛА
return lines.map(line => ({
  json: {
    log_line: line,
    type: logType,
    rules: rulesJson // Пробрасываем правила как JSON-объект каждому элементу
  }
}));

