const inputItem = $json || {};
const logType = inputItem.type || 'ssh';
const logLine = inputItem.log_line || '';
const rulesJson = inputItem.rules || {}; // Правила уже здесь!

const patterns = rulesJson[logType] || [];
const flags = logType === 'journalctl' ? 'i' : '';

const matchedPattern = patterns.find(pattern => {
  try {
    return new RegExp(pattern, flags).test(logLine);
  } catch (e) {
    return false;
  }
});

return {
  json: {
    log_line: logLine,
    log_type: logType,
    is_suspicious: Boolean(matchedPattern),
    matched_rule: matchedPattern || null
  }
};
